function pointsBalance(acct) {
  const rows = DB.portfolio.points.filter((p) => p.accountId === acct); const horizon = addDays(today(), 60);
  const lots = rows.filter((r) => r.points > 0).map((r) => ({ ...r, left: r.points })).sort((a, b) => (a.expiresOn < b.expiresOn ? -1 : 1));
  let spend = -rows.filter((r) => r.points < 0).reduce((a, r) => a + r.points, 0); for (const l of lots) { const u = Math.min(l.left, spend); l.left -= u; spend -= u; }
  const avail = lots.filter((l) => l.expiresOn >= today()); const pts = avail.reduce((a, l) => a + l.left, 0);
  const val = avail.reduce((a, l) => a + Math.round(l.left * l.valuePaise / Math.max(1, l.points)), 0);
  const cards = {}; for (const l of avail) { cards[l.userCardId] = cards[l.userCardId] || { userCardId: l.userCardId, points: 0, valuePaise: 0 }; cards[l.userCardId].points += l.left; cards[l.userCardId].valuePaise += Math.round(l.left * l.valuePaise / Math.max(1, l.points)); }
  return { points: pts, valuePaise: val, expiringSoon: avail.filter((l) => l.expiresOn <= horizon).reduce((a, l) => a + l.left, 0), horizonDays: 60, cards: Object.values(cards) };
}
handle('GET', '/v1/rewards/balance', (q) => ok(pointsBalance(q.acct)));
