handle('POST', '/v1/calc/ledger', (q) => { const b = q.body || {}; const base = b.cycleStart; const r = DexCalc.accrue(txnsN(b.transactions, base), T_(b.terms), 0, dayN(b.cycleEnd, base), (b.openingLots || []).map((l) => DexCalc.lot(dayN(l.date, base), l.bucket, DexCalc.rupees(l.remainingPaise), DexCalc.percent(l.aprBps), l.referenceNumber)), !!b.graceActive); return ok({ totalInterestPaise: DexCalc.paise(r.totalInterest), closingLots: r.closingLots.map((l) => ({ date: addDays(base, l.day), bucket: l.bucket, remainingPaise: DexCalc.paise(l.remaining), aprBps: Number(DexCalc.setScale(l.apr, 2, 'HALF_UP').u), referenceNumber: l.ref })) }); });
handle('POST', '/v1/calc/minimum-due', (q) => { const b = q.body || {}; return ok({ minimumDuePaise: DexCalc.minDuePaise(b.terms, b) }); });
handle('POST', '/v1/calc/late-fee', (q) => { const b = q.body || {}; const f = DexCalc.lateFee(b.outstandingBalancePaise, b.tiers || []); return ok({ lateFeePaise: f, gstOnLateFeePaise: DexCalc.paise(DexCalc.gst(DexCalc.rupees(f))), delinquency: DexCalc.delinquency(b.daysOverdue || 0) }); });
handle('POST', '/v1/calc/utilization', (q) => { const b = q.body || {}; const u = DexCalc.utilization(b.spentPaise, b.creditLimitPaise); return ok({ utilization: u, overlimitFeePaise: b.overlimitFee ? DexCalc.overlimitFee(u.overLimitPaise, b.overlimitFee) : 0 }); });
handle('POST', '/v1/calc/custom-fees', (q) => { const b = q.body || {}; return ok(DexCalc.customFees(b.fees, b.balancePaise, b.cycleNumber || 1)); });
handle('POST', '/v1/calc/scenarios/full-payment', (q) => { const b = q.body || {}; return ok(DexCalc.fullPayment(b.statementBalancePaise, b.customFees || [])); });
handle('POST', '/v1/calc/scenarios/partial-payment', (q) => { const b = q.body || {}; const base = b.cycleStart; return ok(DexCalc.partialPayment(T_(b.terms), txnsN(b.transactions, base), 0, dayN(b.cycleEnd, base), b.paymentPaise, !!b.graceActiveThisCycle, txnsN(b.nextCycleTransactions, base), b.nextCycleStart ? dayN(b.nextCycleStart, base) : null, b.nextCycleEnd ? dayN(b.nextCycleEnd, base) : null)); });
handle('POST', '/v1/calc/scenarios/no-payment', (q) => { const b = q.body || {}; return ok(DexCalc.noPayment(T_(b.terms), b.lateFeeTiers || DexEmi.LATE_TIERS, b.overlimitFee || null, b.statementBalancePaise, b.creditLimitPaise ?? null, b.cycleLengthDays || 30)); });
handle('POST', '/v1/calc/scenarios/minimum-payment', (q) => { const b = q.body || {}; need((b.maxCycles || 360) <= 600, 'maxCycles', 'OUT_OF_RANGE', '≤ 600'); return ok(DexCalc.minimumOnly(T_(b.terms), b.minimumDueTerms || DexEmi.DEFAULT_MD, b.startingPrincipalPaise, b.cycleLengthDays || 30, b.maxCycles || 360, b.creditLimitPaise ?? null, b.overlimitFee || null)); });
handle('POST', '/v1/calc/repayment-path', (q) => { const b = q.body || {}; need((b.cards || []).length >= 1 && b.cards.length <= 20, 'cards', 'SIZE', '1..20'); return ok(DexCalc.repaymentPath(b.cards, b.monthlyBudgetPaise)); });
handle('POST', '/v1/calc/exit-paths', (q) => { const b = q.body || {}; return ok(DexCalc.exitPaths(T_(b.terms), b.minimumDueTerms || DexEmi.DEFAULT_MD, b.currentBalancePaise, b.cycleLengthDays || 30, b.targetCyclesOptions || [3, 6, 12])); });

