const budView = (b) => ({ id: b.id, name: b.name, period: b.period, categoryPath: b.categoryPath, limitPaise: b.limitPaise, rollover: b.rollover, alertThresholds: b.alertThresholds, startsOn: b.startsOn, endsOn: b.endsOn, status: b.status, createdAt: b.createdAt, updatedAt: b.updatedAt, version: b.version });
const myBud = (q) => { const b = DB.planning.budgets.find((x) => x.id === q.params.id && x.accountId === q.acct); if (!b) fail(404, 'NOT_FOUND', 'Budget'); return b; };
handle('POST', '/v1/budgets', (q) => { requireIdem(q); const b = q.body || {}; need((b.name || '').length >= 1, 'name', 'REQUIRED', 'A name'); need(['weekly', 'monthly', 'custom'].includes(b.period), 'period', 'INVALID', 'weekly|monthly|custom'); need(b.limitPaise > 0, 'limitPaise', 'INVALID', '> 0'); if (b.categoryPath) need(DB.ledger.categories.some((c) => c.path === b.categoryPath) || /^[a-z]+(\.[a-z_]+){0,3}$/.test(b.categoryPath), 'categoryPath', 'INVALID', 'An ltree path'); if (b.period === 'custom') need(b.endsOn, 'endsOn', 'REQUIRED', 'Custom periods need an end');
  const x = { id: uuid7(), accountId: q.acct, name: b.name, period: b.period, categoryPath: b.categoryPath || null, limitPaise: b.limitPaise, rollover: !!b.rollover, alertThresholds: b.alertThresholds || [50, 80, 100], startsOn: b.startsOn || today(), endsOn: b.endsOn || null, status: 'active', createdAt: nowIso(), updatedAt: nowIso(), version: 0 };
  DB.planning.budgets.push(x); emit('dexter.planning.budget.v1', 'planning.budget.created', q.acct, { budgetId: x.id }); return ok(budView(x), 201, etag(x)); });
handle('GET', '/v1/budgets', (q) => ok((({ data, page: pg }) => ({ data: data.map(budView), page: pg }))(page(DB.planning.budgets.filter((b) => b.accountId === q.acct && b.status !== 'ended').sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1)), q, (r) => [r.createdAt, r.id]))));
handle('GET', '/v1/budgets/status', (q) => ok({ data: DB.planning.budgets.filter((b) => b.accountId === q.acct && b.status === 'active').map((b) => ({ budget: budView(b), current: budgetStatus(b) })), asOf: today() }));
handle('GET', '/v1/budgets/{id}', (q) => { const b = myBud(q); return ok(budView(b), 200, etag(b)); });
handle('GET', '/v1/budgets/{id}/history', (q) => { const b = myBud(q); const rows = [...DB.planning.spend.values()].filter((r) => r.budgetId === b.id).map((r) => { const s = budgetStatus(b, r.periodStart); return { periodStart: r.periodStart, periodEnd: s.periodEnd, limitPaise: b.limitPaise, spentPaise: r.spentPaise, usedBps: Math.round(r.spentPaise / b.limitPaise * 10000), overLimit: r.spentPaise > b.limitPaise }; }).sort((a, b) => (a.periodStart < b.periodStart ? 1 : -1)); return ok(page(rows, q, (r) => [r.periodStart])); });
handle('PATCH', '/v1/budgets/{id}', (q) => { const b = myBud(q); checkIfMatch(q, b); const p = q.body || {}; for (const k of Object.keys(p)) need(['name', 'limitPaise', 'rollover', 'alertThresholds', 'endsOn', 'status'].includes(k), k, 'UNKNOWN_FIELD', 'Not patchable'); Object.assign(b, p); b.version++; b.updatedAt = nowIso(); return ok(budView(b), 200, etag(b)); });
handle('DELETE', '/v1/budgets/{id}', (q) => { const b = myBud(q); b.status = 'ended'; b.endsOn = today(); b.version++; return ok(null, 204); });
const liaView = (l) => ({ ...l });
const myLia = (q) => { const l = DB.planning.liabilities.find((x) => x.id === q.params.id && x.accountId === q.acct); if (!l) fail(404, 'NOT_FOUND', 'Liability'); return l; };
handle('POST', '/v1/liabilities', (q) => { requireIdem(q); const b = q.body || {}; need(['loan', 'card_emi', 'bnpl', 'other'].includes(b.kind), 'kind', 'INVALID', 'loan|card_emi|bnpl|other'); need(b.principalPaise > 0, 'principalPaise', 'INVALID', '> 0'); need(b.tenureMonths >= 1 && b.tenureMonths <= 360, 'tenureMonths', 'OUT_OF_RANGE', '1..360'); const l = makeLiability(q.acct, b.kind, b.lender || 'Lender', b.principalPaise, b.aprBps || 0, b.tenureMonths, b.startDate || addDays(today(), 30)); emit('dexter.planning.liability.v1', 'planning.liability.changed', q.acct, { liabilityId: l.id }); return ok(liaView(l), 201, etag(l)); });
handle('GET', '/v1/liabilities', (q) => ok(page(DB.planning.liabilities.filter((l) => l.accountId === q.acct).sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1)), q, (r) => [r.createdAt, r.id])));
handle('GET', '/v1/liabilities/{id}', (q) => { const l = myLia(q); return ok(liaView(l), 200, etag(l)); });
handle('GET', '/v1/liabilities/{id}/schedule', (q) => { const l = myLia(q); return ok(page(DB.planning.lschedule[l.id], q, (r) => [r.number])); });
handle('PATCH', '/v1/liabilities/{id}', (q) => { const l = myLia(q); checkIfMatch(q, l); const b = q.body || {}; for (const k of Object.keys(b)) need(['lender', 'status'].includes(k), k, 'UNKNOWN_FIELD', 'Not patchable'); Object.assign(l, b); l.version++; return ok(liaView(l), 200, etag(l)); });
handle('DELETE', '/v1/liabilities/{id}', (q) => { const l = myLia(q); l.status = 'closed'; l.version++; return ok(null, 204); });
function scenarioEval(s) {
  const base = s.baseSnapshot; let income = base.monthlyIncomePaise; const bud = new Map(base.budgets.map((b) => [b.id, { ...b }])); const lia = new Map(base.liabilities.map((l) => [l.id, { ...l, added: false }]));
  for (const a of s.adjustments) { if (a.kind === 'setMonthlyIncome') income = a.amountPaise; else if (a.kind === 'setBudgetLimit' && bud.has(a.budgetId)) bud.get(a.budgetId).limitPaise = a.limitPaise; else if (a.kind === 'removeLiability') lia.delete(a.liabilityId); else if (a.kind === 'addLiability') { const id = 'new-' + lia.size; lia.set(id, { id, lender: a.lender, emiPaise: DexCalc.emi(a.principalPaise, a.aprBps, a.tenureMonths), added: true }); } }
  const before = base.budgets.reduce((x, b) => x + b.limitPaise, 0) + base.liabilities.reduce((x, l) => x + l.emiPaise, 0);
  const lines = [...[...bud.values()].map((b) => ({ kind: 'budget', id: b.id, label: b.name, monthlyPaise: b.limitPaise, added: false })), ...[...lia.values()].map((l) => ({ kind: 'liability', id: l.id, label: l.lender, monthlyPaise: l.emiPaise, added: l.added }))];
  const after = lines.reduce((x, l) => x + l.monthlyPaise, 0);
  return { monthlyIncomePaise: income, monthlyOutgoBeforePaise: before, monthlyOutgoAfterPaise: after, deltaPaise: after - before, surplusBeforePaise: base.monthlyIncomePaise - before, surplusAfterPaise: income - after, feasible: income >= after, lines };
}
const myScn = (q) => { const s = DB.planning.scenarios.find((x) => x.id === q.params.id && x.accountId === q.acct); if (!s) fail(404, 'NOT_FOUND', 'Scenario'); return s; };
handle('POST', '/v1/scenarios', (q) => { requireIdem(q); const b = q.body || {}; const snap = { monthlyIncomePaise: b.monthlyIncomePaise || 0, budgets: DB.planning.budgets.filter((x) => x.accountId === q.acct && x.status === 'active' && x.period === 'monthly' && x.categoryPath).map((x) => ({ id: x.id, name: x.name, limitPaise: x.limitPaise })), liabilities: DB.planning.liabilities.filter((l) => l.accountId === q.acct && l.status === 'active').map((l) => ({ id: l.id, lender: l.lender, emiPaise: l.emiPaise })) };
  for (const a of b.adjustments || []) need(['setMonthlyIncome', 'setBudgetLimit', 'addLiability', 'removeLiability'].includes(a.kind), 'adjustments.kind', 'INVALID', 'setMonthlyIncome|setBudgetLimit|addLiability|removeLiability');
  const s = { id: uuid7(), accountId: q.acct, name: b.name || 'What if', baseSnapshot: snap, adjustments: b.adjustments || [], createdAt: nowIso(), updatedAt: nowIso(), version: 0 }; DB.planning.scenarios.unshift(s); return ok(s, 201, etag(s)); });
handle('GET', '/v1/scenarios', (q) => ok(page(DB.planning.scenarios.filter((s) => s.accountId === q.acct), q, (r) => [r.createdAt, r.id])));
handle('GET', '/v1/scenarios/{id}', (q) => { const s = myScn(q); return ok(s, 200, etag(s)); });
handle('PATCH', '/v1/scenarios/{id}', (q) => { const s = myScn(q); checkIfMatch(q, s); const b = q.body || {}; for (const k of Object.keys(b)) need(['name', 'adjustments'].includes(k), k, 'UNKNOWN_FIELD', 'The snapshot is never re-taken'); Object.assign(s, b); s.version++; s.updatedAt = nowIso(); return ok(s, 200, etag(s)); });
handle('POST', '/v1/scenarios/{id}:evaluate', (q) => ok(scenarioEval(myScn(q))));

/* ================= reco ================= */
handle('GET', '/v1/recommendations', (q) => {
  if (q.query.cardProductIds) { const ids = q.query.cardProductIds.split(','); need(ids.length <= 50, 'cardProductIds', 'TOO_MANY', '≤ 50'); const v = scoreAll(q.acct, ids); return ok({ ...v, fresh: true, computedAt: nowIso(), cached: false }); }
  const v = recoRead(q.acct); return ok(v, 200, { ETag: `"${v.stateHash}"` });
});
handle('GET', '/v1/recommendations/explain/{cardProductId}', (q) => ok(explain(q.acct, q.params.cardProductId)));
handle('GET', '/v1/recommendations/wallet', (q) => { const n = +(q.query.size || 3); need(n >= 1 && n <= 3, 'size', 'OUT_OF_RANGE', '1..3'); const ent = DB.billing.plans.find((p) => p.code === DB.identity.accounts[q.acct].tier).entitlements; if (!ent.walletOptimizer) fail(402, 'ENTITLEMENT_REQUIRED', 'Wallet optimizer is a PREMIUM feature'); return ok(wallet(q.acct, n)); });
handle('GET', '/v1/recommendations/best-card', (q) => { const a = +q.query.amountPaise; need(q.query.merchantId || q.query.category, 'merchantId', 'REQUIRED', 'merchantId or category'); need(Number.isInteger(a) && a > 0, 'amountPaise', 'INVALID', 'A positive amount'); return ok(bestCard(q.acct, { merchantId: q.query.merchantId, category: q.query.category, amountPaise: a })); });
handle('POST', '/v1/recommendations/stream-ticket', (q) => { const t = 'st_' + uuid7().replace(/-/g, '').slice(0, 24); DB.reco.tickets[t] = { acct: q.acct, exp: now().getTime() + 60000, used: false }; return ok({ ticket: t, expiresInSeconds: 60 }, 201); });
handle('GET', '/v1/recommendations/stream', (q) => { if ((q.headers.Accept || 'text/event-stream') !== 'text/event-stream') fail(406, 'NOT_ACCEPTABLE', 'text/event-stream only'); const t = DB.reco.tickets[q.query.ticket]; if (!t || t.used || t.exp < now().getTime()) fail(401, 'STREAM_TICKET_INVALID', 'Spent, expired or unknown ticket'); t.used = true; const v = recoRead(t.acct); return ok({ _stream: true, acct: t.acct, first: q.headers['Last-Event-ID'] === v.stateHash ? { event: 'recommendation.unchanged', id: v.stateHash, data: {} } : { event: 'recommendation.updated', id: v.stateHash, data: v } }, 200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-store' }); });

/* ================= billing ================= */
const planView = (p) => ({ code: p.code, name: p.name, pricePaise: p.pricePaise, gstPaise: Math.round(p.pricePaise * 0.18), totalPaise: p.pricePaise + Math.round(p.pricePaise * 0.18), interval: p.interval, entitlements: p.entitlements });
const subView = (s) => { const p = DB.billing.plans.find((x) => x.code === s.planCode); return { id: s.id, planCode: s.planCode, planName: p.name, interval: p.interval, status: s.status, currentPeriodStart: s.currentPeriodStart, currentPeriodEnd: s.currentPeriodEnd, cancelAtPeriodEnd: s.cancelAtPeriodEnd, canceledAt: s.canceledAt, endedAt: s.endedAt, provider: s.provider, createdAt: s.createdAt, updatedAt: s.updatedAt, version: s.version }; };
const liveSub = (acct) => DB.billing.subs.find((s) => s.accountId === acct && ['trialing', 'active', 'past_due', 'incomplete'].includes(s.status));
handle('GET', '/v1/plans', () => ok({ data: DB.billing.plans.filter((p) => p.active).map(planView) }));
handle('GET', '/v1/plans/{code}', (q) => { const p = DB.billing.plans.find((x) => x.code.toLowerCase() === q.params.code.toLowerCase()); if (!p) fail(404, 'NOT_FOUND', 'Plan'); return ok(planView(p)); });
function setTier(acct, tier) { DB.identity.accounts[acct].tier = tier; emit('dexter.billing.entitlements.v1', 'billing.entitlements.changed', acct, { tier, entitlements: DB.billing.plans.find((p) => p.code === tier).entitlements }); }
handle('POST', '/v1/subscriptions/checkout', (q) => {
  requireIdem(q); if (Date.parse(nowIso()) - Date.parse(q.tok.stepUpAt) > 600000) fail(401, 'STEP_UP_REQUIRED', 'Billing changes need a sign-in within 10 minutes');
  const b = q.body || {}; const p = DB.billing.plans.find((x) => x.code === b.plan); need(p && p.code !== 'FREE', 'plan', 'INVALID', 'PREMIUM | VIP'); need(/^pm_/.test(b.paymentMethod || ''), 'paymentMethod', 'INVALID', 'pm_… token from the provider'); need(/^[A-Z]{2}$/.test(b.billingState || ''), 'billingState', 'INVALID', 'Two-letter state code');
  if (liveSub(q.acct)) fail(409, 'SUBSCRIPTION_EXISTS', 'Another subscription is live — cancel it first');
  const outcome = b.paymentMethod === 'pm_card_declined' ? 'failed' : b.paymentMethod === 'pm_delayed' ? 'pending' : 'succeeded';
  const end = p.interval === 'year' ? DexCalc.addMonths(today(), 12) : DexCalc.addMonths(today(), 1);
  const s = { id: uuid7(), accountId: q.acct, planCode: p.code, status: outcome === 'succeeded' ? 'active' : outcome === 'pending' ? 'incomplete' : 'incomplete_expired', currentPeriodStart: nowIso(), currentPeriodEnd: end + 'T00:00:00Z', cancelAtPeriodEnd: false, canceledAt: null, endedAt: null, provider: 'mock', createdAt: nowIso(), updatedAt: nowIso(), version: 0, providerSubId: 'sub_' + uuid7().slice(0, 12) };
  DB.billing.subs.unshift(s); const pay = { id: uuid7(), accountId: q.acct, subscriptionId: s.id, amountPaise: p.pricePaise + Math.round(p.pricePaise * 0.18), status: outcome, providerPaymentId: 'pay_' + uuid7().slice(0, 12), createdAt: nowIso() }; DB.billing.payments.unshift(pay);
  if (outcome === 'succeeded') { makeInvoice(q.acct, s, p, b.billingState, nowIso()); setTier(q.acct, p.code); emit('dexter.billing.subscription.v1', 'billing.subscription.changed', q.acct, { status: 'active', planCode: p.code }); }
  audit('user', q.acct, 'billing.checkout', 'subscription', s.id, { outcome });
  if (outcome === 'failed') return ok({ subscription: subView(s), payment: pay, outcome }, 402);
  return ok({ subscription: subView(s), payment: pay, outcome }, outcome === 'pending' ? 202 : 201);
});
handle('GET', '/v1/subscriptions/me', (q) => { const s = liveSub(q.acct) || DB.billing.subs.find((x) => x.accountId === q.acct); if (!s) fail(404, 'NOT_FOUND', 'No subscription ever'); return ok(subView(s), 200, etag(s)); });
handle('POST', '/v1/subscriptions/me:cancel', (q) => { if (Date.parse(nowIso()) - Date.parse(q.tok.stepUpAt) > 600000) fail(401, 'STEP_UP_REQUIRED', 'Sign in again'); const s = liveSub(q.acct); if (!s) fail(404, 'NOT_FOUND', 'No live subscription'); if (!s.cancelAtPeriodEnd) { s.cancelAtPeriodEnd = true; s.canceledAt = nowIso(); s.version++; emit('dexter.billing.subscription.v1', 'billing.subscription.changed', q.acct, { status: 'cancel_at_period_end', planCode: s.planCode }); } return ok(subView(s)); });
handle('GET', '/v1/entitlements/me', (q) => { const tier = DB.identity.accounts[q.acct].tier; const ov = DB.billing.overrides.filter((o) => o.accountId === q.acct && o.expiresAt > nowIso()); const ent = { ...DB.billing.plans.find((p) => p.code === tier).entitlements }; for (const o of ov) ent[o.key] = o.value; return ok({ tier, entitlements: ent, overrides: ov.map(({ accountId, ...o }) => o) }, 200, { 'Cache-Control': 'private, max-age=60' }); });
handle('GET', '/v1/invoices', (q) => ok(page(DB.billing.invoices.filter((i) => i.accountId === q.acct), q, (r) => [r.issuedAt, r.id])));
handle('GET', '/v1/invoices/{id}', (q) => { const i = DB.billing.invoices.find((x) => x.id === q.params.id && x.accountId === q.acct); if (!i) fail(404, 'NOT_FOUND', 'Invoice'); return ok(i); });
handle('POST', '/v1/webhooks/{provider}', (q) => {
  if (q.params.provider !== 'mock' && q.params.provider !== 'razorpay') fail(404, 'PROVIDER_UNKNOWN', q.params.provider);
  const sig = q.headers['Webhook-Signature'] || ''; if (!/^t=\d+,v1=[0-9a-f]{16,}$/.test(sig)) fail(400, 'WEBHOOK_SIGNATURE_INVALID', 'HMAC over "<t>.<body>", ±5 min');
  const b = q.body || {}; const k = q.params.provider + '|' + b.id; if (DB.billing.webhooks.has(k)) return ok({ status: 'duplicate', eventId: b.id, outcome: 'no-op' }); DB.billing.webhooks.add(k);
  const s = DB.billing.subs.find((x) => x.status === 'incomplete' && x.accountId === (b.accountId || q.acct || ASHA)) || DB.billing.subs.find((x) => x.status === 'incomplete');
  if (b.type === 'payment.succeeded' && s) { s.status = 'active'; s.version++; const p = DB.billing.plans.find((x) => x.code === s.planCode); makeInvoice(s.accountId, s, p, 'KA', nowIso()); setTier(s.accountId, p.code); emit('dexter.billing.subscription.v1', 'billing.subscription.changed', s.accountId, { status: 'active', planCode: p.code }); return ok({ status: 'processed', eventId: b.id, outcome: 'subscription activated' }); }
  if (b.type === 'payment.failed' && s) { s.status = 'incomplete_expired'; s.version++; return ok({ status: 'processed', eventId: b.id, outcome: 'subscription closed' }); }
  return ok({ status: 'ignored', eventId: b.id, outcome: 'nothing pending' });
});

