const SAGA_SVCS = ['identity', 'ledger', 'catalog', 'portfolio', 'planning', 'reco', 'billing', 'commerce', 'audit'];
function privacyStart(q, kind) {
  requireIdem(q); if (Date.parse(nowIso()) - Date.parse(q.tok.stepUpAt) > 600000) fail(401, 'STEP_UP_REQUIRED', 'Sign in within the last 10 minutes');
  if (DB.audit.privacy.some((r) => r.accountId === q.acct && r.kind === kind && ['running', 'failed'].includes(r.status))) fail(409, 'PRIVACY_REQUEST_RUNNING', 'One of this kind is already running');
  const r = { id: uuid7(), accountId: q.acct, kind, status: 'running', phase: kind === 'export' ? 'collect' : 'freeze', attempt: 1, answers: Object.fromEntries(SAGA_SVCS.map((s) => [s, 'pending'])), createdAt: nowIso(), completedAt: null, downloadUrl: null, downloadExpiresAt: null };
  DB.audit.privacy.unshift(r); audit('user', q.acct, 'privacy.' + kind + '.requested', 'privacy_request', r.id);
  const failAt = kind === 'delete' && q.acct === RAVI ? 'billing' : null; // demo: one participant times out → failed, resumable
  let i = 0; const tick = () => { if (i < SAGA_SVCS.length) { const s = SAGA_SVCS[i++]; if (s === failAt && r.attempt === 1) { r.answers[s] = 'timeout'; r.status = 'failed'; if (window.onSaga) window.onSaga(r); return; } r.answers[s] = kind === 'export' ? 'part-written' : (s === 'catalog' ? 'nothing-held' : 'erased'); if (window.onSaga) window.onSaga(r); if (window.SYNC_SAGA) tick(); else setTimeout(tick, 280); } else { r.status = 'completed'; r.phase = kind === 'export' ? 'zipped' : 'shredded'; r.completedAt = nowIso(); if (kind === 'export') { r.downloadUrl = 'https://objects.dexter.local/exports/' + r.id + '.zip?X-Amz-Expires=86400'; r.downloadExpiresAt = new Date(now().getTime() + 86400000).toISOString(); notify(q.acct, 'privacy', 'privacy.export.ready', 'Your data export is ready', 'Download link valid for 24 hours'); } if (window.onSaga) window.onSaga(r); } };
  if (window.SYNC_SAGA) tick(); else setTimeout(tick, 200); return ok(r, 202);
}
handle('POST', '/v1/privacy/export', (q) => privacyStart(q, 'export'));
handle('POST', '/v1/privacy/delete', (q) => privacyStart(q, 'delete'));
handle('GET', '/v1/privacy/requests', (q) => ok({ data: DB.audit.privacy.filter((r) => r.accountId === q.acct) }));
handle('GET', '/v1/privacy/requests/{id}', (q) => { const r = DB.audit.privacy.find((x) => x.id === q.params.id && x.accountId === q.acct); if (!r) fail(404, 'NOT_FOUND', 'Request'); return ok(r); });
handle('GET', '/v1/admin/audit', (q) => { perm(q, 'audit:read'); let l = DB.audit.log; for (const k of ['actorId', 'action', 'targetType', 'targetId']) if (q.query[k]) l = l.filter((r) => String(r[k]).includes(q.query[k])); const p = page(l, q, (r) => [r.seq]); return ok({ data: p.data.map(({ prevHash, ...r }) => r), page: p.page }); });
handle('POST', '/v1/admin/audit:verify-chain', (q) => { perm(q, 'audit:read'); const rows = [...DB.audit.log].reverse(); let brokenAt = null, reason = null;
  for (let i = 0; i < rows.length; i++) { const r = rows[i]; const prev = i ? rows[i - 1].hash : '0'.repeat(64); if (r.prevHash !== prev) { brokenAt = r.seq; reason = 'LINK_MISMATCH'; break; } const h = hashSync(JSON.stringify([r.seq, r.occurredAt, r.actorType, r.actorId, r.action, r.targetType, r.targetId, JSON.stringify(r.details), r.prevHash])); if (h !== r.hash) { brokenAt = r.seq; reason = 'HASH_MISMATCH'; break; } }
  audit('admin', q.admin.sub, 'audit.chain.verified', 'audit_log', null, { ok: !brokenAt }); return ok({ ok: !brokenAt, checked: rows.length, headSeq: rows.length ? rows[rows.length - 1].seq : 0, brokenAt, reason, anchorsChecked: Math.ceil(rows.length / 50) }); });
handle('GET', '/v1/admin/audit/privacy-requests/{id}', (q) => { perm(q, 'audit:read'); const r = DB.audit.privacy.find((x) => x.id === q.params.id); if (!r) fail(404, 'NOT_FOUND', 'Request'); return ok({ ...r, accountId: r.status === 'completed' && r.kind === 'delete' ? 'pseudo:' + hashSync(r.accountId).slice(0, 16) : r.accountId }); });
handle('POST', '/v1/admin/audit/privacy-requests/{id}:resume', (q) => { perm(q, 'audit:verify'); const r = DB.audit.privacy.find((x) => x.id === q.params.id); if (!r) fail(404, 'NOT_FOUND', 'Request'); if (r.status !== 'failed') fail(409, 'PRIVACY_REQUEST_NOT_FAILED', r.status); r.status = 'running'; r.attempt++; for (const s of SAGA_SVCS) if (r.answers[s] === 'timeout') r.answers[s] = 'erased'; r.status = 'completed'; r.completedAt = nowIso(); return ok(r); });
handle('GET', '/v1/admin/activity/dashboard', (q) => { perm(q, 'audit:read'); const hrs = +(q.query.hours || 24); need(hrs >= 1 && hrs <= 336, 'hours', 'OUT_OF_RANGE', '1..336'); const since = new Date(Date.parse(NOW_ISO) - hrs * 3600000).toISOString(); const rows = DB.audit.activity.filter((r) => r.hour >= since); const by = {}; for (const r of rows) { const x = (by[r.service] = by[r.service] || { requests: 0, clientErrors: 0, serverErrors: 0, avgMsSum: 0, n: 0, maxMs: 0 }); x.requests += r.requests; x.clientErrors += r.clientErrors; x.serverErrors += r.serverErrors; x.avgMsSum += r.avgMs; x.n++; x.maxMs = Math.max(x.maxMs, r.maxMs); }
  return ok({ hours: hrs, totals: Object.fromEntries(Object.entries(by).map(([s, x]) => [s, { requests: x.requests, clientErrors: x.clientErrors, serverErrors: x.serverErrors, avgMs: Math.round(x.avgMsSum / x.n), maxMs: x.maxMs }])), byHour: rows }); });
